import React from 'react';
import { SalesReportCard } from './SalesReportCard';
import { SalesReportWorkspace } from './SalesReportWorkspace';

const scopeFor = (user) => user?.is_superuser ? 'org' : user?.role === 'hr_admin' ? 'org' : user?.role === 'manager' ? 'team' : 'mine';

export default function SalesV2DashboardWidgets({ currentUser, onFileNow }) {
  const scope = scopeFor(currentUser);
  return <section className={`sales-v2-dashboard sales-v2-dashboard-${scope}`} aria-label="Sales and marketing reports"><div className="sales-v2-widget-grid"><SalesReportCard title={scope === 'mine' ? "Today's report" : scope === 'team' ? 'Team submissions today' : 'Organization compliance'} value="View report" onAction={onFileNow} /><SalesReportCard title={scope === 'mine' ? 'Visits today' : 'Registrations this month'} value="Open workspace" onAction={onFileNow} /><SalesReportCard title={scope === 'mine' ? 'Open appointments' : 'Top performers'} value="View detail" onAction={onFileNow} /></div><SalesReportWorkspace scope={scope} /></section>;
}
